classDiagram
class Document {
 +String id
 +String source
 +append(chunk)
 +finish()
}
class PreparedBlock {
 +String id
 +Float naturalWidth
 +layout(width)
}
class Cache {
 +Int capacity
 +lookup(key)
 +insert(value)
}
Document "1" *-- "many" PreparedBlock : contains
Document --> Cache : reuses

erDiagram
 DOCUMENT ||--o{ BLOCK : contains
 BLOCK ||--o{ RESOURCE : references
 DOCUMENT ||--o{ REVISION : records
 DOCUMENT {
  string id PK
  string title
 }
 BLOCK {
  string id PK
  string document_id FK
  int byte_offset
 }
 RESOURCE {
  string id PK
  string url
 }
 REVISION {
  int revision PK
  string document_id FK
 }
